#include <stdio.h>

/* teste do desafio o-swap — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A funcao do aluno nao devolve nem imprime: o teste declara as variaveis,
   entrega os ENDERECOS delas e confere o que sobrou em cada uma. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void oSwap(int *a, int *b);

SM_TEST(troca_dois_positivos) {
    int x = 3;
    int y = 8;
    oSwap(&x, &y);
    checa_int("o primeiro recebeu o valor do segundo", x, 8,
              "depois da troca, x fica com o 8 que estava em y");
    checa_int("o segundo recebeu o valor do primeiro", y, 3,
              "depois da troca, y fica com o 3 que estava em x — nenhum valor se perde");
}

SM_TEST(troca_com_negativo_e_zero) {
    int a = -5;
    int b = 0;
    oSwap(&a, &b);
    checa_int("o negativo foi para a segunda casa", b, -5,
              "a troca nao olha o sinal: vale para qualquer int");
    checa_int("o zero foi para a primeira casa", a, 0,
              "o zero e um valor como outro qualquer e tambem viaja na troca");
}

SM_TEST(trocar_uma_casa_com_ela_mesma) {
    int v = 7;
    oSwap(&v, &v);
    checa_int("trocar uma casa com ela mesma nao muda nada", v, 7,
              "os dois enderecos sao o mesmo: o valor sai e volta para o mesmo lugar");
}

solutionCode:
void oSwap(int *a, int *b) {
    int guarda = *a;
    *a = *b;
    *b = guarda;
}
